        // Month 1-12, weekday 1-7 Monday first, tutorial step 1-based,
        // difficulty by its enum ordinal. Out of range is a bug, not a
        // missing translation, so these throw rather than blank.
        public static string Month(int month) => _v[MonthIdx[month - 1]];
        public static string MonthShort(int month) => _v[MonthShortIdx[month - 1]];
        public static string Day(int isoWeekday) => _v[DayIdx[isoWeekday - 1]];
        public static string TutorialLine(int step) => _v[TutIdx[step - 1]];
        public static string DifficultyName(int ordinal) => _v[DifficultyIdx[ordinal]];

